pub fn run(args: Args) -> anyhow::Result<()> {
    let requested = if args.decks.is_empty() {
        bundled_paths()
    } else {
        args.decks
    };
    if !(aperture_core::MIN_PLAYERS..=aperture_core::MAX_PLAYERS).contains(&requested.len()) {
        anyhow::bail!(
            "selfplay needs 2..=4 --deck paths (got {})",
            requested.len()
        );
    }

    let mut lists = Vec::with_capacity(requested.len());
    let mut sources = Vec::with_capacity(requested.len());
    for (index, path) in requested.iter().enumerate() {
        let (fallback, name) = if index % 2 == 0 {
            (decks::BUNDLED_TEMUR, "Temur Beats")
        } else {
            (decks::BUNDLED_IZZET, "Izzet Control")
        };
        let (deck, source) = decks::load(path, fallback, name, args.deck_explicit)?;
        lists.push(deck);
        sources.push(source);
    }
    let seats = lists.len();

    let ai = AiSettings {
        use_decider: args.decider_seat.is_some(),
        decider_timeout_ms: args.decider_timeout_ms,
        human_seat: 0,
        ai_seats: (0..seats as u8).collect(),
        ..AiSettings::default()
    };

    let mut policies: Vec<Box<dyn Policy>> = (0..seats)
        .map(|_| Box::new(HeuristicPolicy::new()) as Box<dyn Policy>)
        .collect();
    let mut decider_note = None;
    if let Some(seat) = args.decider_seat {
        if seat as usize >= seats {
            decider_note = Some(format!(
                "decider seat {seat} is outside this {seats}-seat game; all seats use the heuristic"
            ));
        } else {
            let config = DeciderConfig {
                timeout_ms: args.decider_timeout_ms,
                ..DeciderConfig::default()
            };
            match DeciderPolicy::new(config) {
                Ok(policy) => {
                    policies[seat as usize] = Box::new(policy);
                    decider_note = Some(format!(
                        "seat {seat} uses decider-2b with heuristic fallback"
                    ));
                }
                Err(err) => {
                    decider_note = Some(format!(
                        "decider request rejected ({err}); all seats use the heuristic"
                    ));
                }
            }
        }
    }

    let commander_setup: Vec<aperture_core::CommanderSetup> = args
        .commanders
        .iter()
        .map(|(seat, card)| aperture_core::CommanderSetup {
            seat: *seat,
            card: *card,
        })
        .collect();
    if args.profile.has_command_zone() && args.commanders.len() != lists.len() {
        anyhow::bail!(
            "{} needs exactly one --commander per deck ({} commander(s), {} deck(s))",
            args.profile.label(),
            args.commanders.len(),
            lists.len()
        );
    }
    let (mut game, mut log) = match args.profile {
        aperture_core::Profile::Practice20 => Game::new_logged(args.seed, &lists),
        aperture_core::Profile::CommandZone20 => {
            Game::new_command_zone_logged(args.seed, &lists, &args.commanders)
        }
        aperture_core::Profile::CommanderCombat40 => {
            Game::new_commander_combat_logged(args.seed, &lists, &args.commanders)
        }
    }
    .map_err(|err| anyhow::anyhow!("{err}"))?;
    let mut replay = match args.profile {
        aperture_core::Profile::Practice20 => Replay::new(
            args.seed,
            game.state.first_player,
            lists.clone(),
            ai.clone(),
        ),
        aperture_core::Profile::CommandZone20 => Replay::new_command_zone(
            args.seed,
            game.state.first_player,
            lists.clone(),
            commander_setup,
            ai.clone(),
        ),
        aperture_core::Profile::CommanderCombat40 => Replay::new_commander_combat(
            args.seed,
            game.state.first_player,
            lists.clone(),
            commander_setup,
            ai.clone(),
        ),
    }
    .map_err(|err| anyhow::anyhow!("{err}"))?;
    let limits = SelfplayLimits {
        max_steps: args.max_steps,
        max_millis: args.max_millis,
    };
    let outcome = play_to_end(&mut game, &mut policies, limits, &mut log, &mut replay);
    replay.outcome = game.state.outcome.clone();
    replay.final_digest = game.digest();

    if args.verbose {
        for event in &log {
            println!("{}", aperture_core::view::render_event(&game, 0, event));
        }
    }

    let casts = log
        .iter()
        .filter(|e| matches!(e, Event::Cast { .. }))
        .count();
    let attacks = log
        .iter()
        .filter(
            |e| matches!(e, Event::AttackersDeclared { attackers, .. } if !attackers.is_empty()),
        )
        .count();
    let blocks = log
        .iter()
        .filter(|e| matches!(e, Event::BlockersDeclared { blocks, .. } if !blocks.is_empty()))
        .count();
    let damage = log
        .iter()
        .filter(|e| matches!(e, Event::Damage { .. }))
        .count();
    let counters = log
        .iter()
        .filter(|e| matches!(e, Event::Countered { .. }))
        .count();
    // Terminal rows are pruned when a recipient leaves, so final acceptance
    // reporting derives aggregate totals and the loss count from typed events.
    let mut commander_totals: std::collections::BTreeMap<(u32, u8), u32> =
        std::collections::BTreeMap::new();
    for event in &log {
        if let Event::CommanderDamage {
            commander,
            recipient,
            amount,
            ..
        } = event
        {
            *commander_totals
                .entry((commander.0, *recipient))
                .or_insert(0) += *amount;
        }
    }
…
}

